using System.Security.Claims;
using System.Text;
using ClosedXML.Excel;
using EmployeeMonitoringAPI.Data;
using EmployeeMonitoringAPI.Interfaces;
using EmployeeMonitoringAPI.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace EmployeeMonitoringAPI.Controllers;

[ApiController,Route("api/hr/enterprise"),Authorize(Roles="HR")]
public sealed class HrEnterpriseController(ApplicationDbContext db,IAuditService audit):ControllerBase
{
 int HrId()=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);IQueryable<User>People()=>db.Users.Where(x=>x.AssignedHrId==HrId()&&(x.Role=="Employee"||x.Role=="Manager"));
 [HttpGet("metadata")]public async Task<IActionResult>Metadata(){var keys=new[]{"EmploymentStatuses","LeaveStatuses","AttendanceStatuses","TrainingStatuses","PerformanceRecommendations","OnboardingStages","OnboardingStageStatuses","ReportTypes"};return Ok(await db.SystemSettings.Where(x=>keys.Contains(x.SettingKey)).ToDictionaryAsync(x=>x.SettingKey,x=>x.SettingValue.Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries)));}
 [HttpGet("people/{id:int}")]
 public async Task<IActionResult>Person(int id)
 {
  var u=await People().AsNoTracking().Include(x=>x.Department).Include(x=>x.Manager).FirstOrDefaultAsync(x=>x.UserId==id);if(u==null)return NotFound();
  var direct=await db.Users.AsNoTracking().Where(x=>x.ManagerId==id&&x.AssignedHrId==HrId()&&x.Role=="Employee").Select(x=>new{x.UserId,x.FullName,x.EmployeeCode,x.Designation,x.IsActive}).ToListAsync();var directIds=direct.Select(x=>x.UserId).ToList();
  var attendance=await db.Attendances.AsNoTracking().Where(x=>x.UserId==id).OrderByDescending(x=>x.AttendanceDate).Take(60).Select(x=>new{x.AttendanceId,x.AttendanceDate,x.CheckInTime,x.CheckOutTime,x.TotalHours,x.EffectiveHours,x.LateMinutes,x.AttendanceStatus,x.Status}).ToListAsync();
  var leave=await db.Leaves.AsNoTracking().Where(x=>x.UserId==id).OrderByDescending(x=>x.AppliedAt).Take(50).Select(x=>new{x.LeaveId,x.LeaveType,x.FromDate,x.ToDate,x.Reason,x.Status,x.AppliedAt,x.ApprovalRemarks}).ToListAsync();
  var projects=await db.ProjectAssignments.AsNoTracking().Where(x=>x.UserId==id&&x.Project!=null).Select(x=>new{x.ProjectId,x.Project!.ProjectName,x.Project.ProjectCode,x.Project.Status,x.Project.ProgressPercentage,x.Project.EndDate}).ToListAsync();
  var performance=await db.PerformanceReviews.AsNoTracking().Where(x=>x.EmployeeId==id).OrderByDescending(x=>x.ReviewDate).Select(x=>new{x.PerformanceReviewId,x.Year,x.Quarter,x.Rating,x.ManagerRemarks,x.PromotionRecommendation,x.ReviewDate,x.IsReleased}).ToListAsync();
  var training=await db.TrainingAssignments.AsNoTracking().Where(x=>x.UserId==id).Select(x=>new{x.TrainingAssignmentId,name=x.TrainingProgram!=null?x.TrainingProgram.Name:null,x.Status,x.Score,x.AssignedAt,x.CompletedAt}).ToListAsync();
  var payroll=await db.PayrollRecords.AsNoTracking().Where(x=>x.EmployeeId==id).OrderByDescending(x=>x.PayPeriod).Take(12).Select(x=>new{x.PayPeriod,x.NetSalary,x.Status}).ToListAsync();
  var documents=await db.DocumentFiles.AsNoTracking().Where(x=>x.UploadedById==id).OrderByDescending(x=>x.UploadedAt).Select(x=>new{x.DocumentId,x.OriginalFileName,x.Category,createdAt=x.UploadedAt}).ToListAsync();
  var emergencyContacts=await db.EmergencyContacts.AsNoTracking().Where(x=>x.UserId==id).Select(x=>new{x.EmergencyContactId,x.Name,x.Relationship,x.Phone,x.Email,x.IsPrimary}).ToListAsync();
  var activity=await db.ActivityLogs.AsNoTracking().Where(x=>x.UserId==id).OrderByDescending(x=>x.CreatedAt).Take(100).Select(x=>new{x.Id,x.Action,x.CreatedAt}).ToListAsync();
  var promotionHistory=await db.PromotionHistories.AsNoTracking().Where(x=>x.UserId==id).OrderByDescending(x=>x.EffectiveDate).Select(x=>new{x.PromotionHistoryId,x.FromDesignation,x.ToDesignation,x.Status,x.EffectiveDate,x.Remarks}).ToListAsync();
  return Ok(new{personal=new{u.UserId,u.ProfileImage,u.FullName,u.Email,u.Username,u.PhoneNumber,u.DateOfBirth,u.Address},job=new{u.EmployeeCode,u.Role,department=u.Department!=null?u.Department.Name:null,u.DepartmentId,u.Designation,manager=u.Manager!=null?u.Manager.FullName:null,u.ManagerId,u.EmploymentType,u.EmploymentStatus,u.WorkLocation,u.DateOfJoining,u.LastLoginAt,u.IsActive},attendance,leave,projects,performance,training,payroll,documents,emergencyContacts,activity,directReports=direct,approvalsPending=u.Role=="Manager"?new{leaves=await db.Leaves.CountAsync(x=>directIds.Contains(x.UserId)&&x.Status=="Pending"),timesheets=await db.WeeklyTimesheets.CountAsync(x=>x.ManagerId==id&&x.Status=="Submitted"),attendanceCorrections=await db.AttendanceRegularizations.CountAsync(x=>directIds.Contains(x.UserId)&&x.Status=="Pending")}:null,promotionHistory});
 }
 [HttpPost("people/{id:int}/emergency-contacts")]public async Task<IActionResult>Emergency(int id,EmergencyContactRequest r){if(!await People().AnyAsync(x=>x.UserId==id))return NotFound();if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.Phone))return BadRequest(new{message="Name and phone are required"});if(r.IsPrimary){var old=await db.EmergencyContacts.Where(x=>x.UserId==id&&x.IsPrimary).ToListAsync();old.ForEach(x=>x.IsPrimary=false);}var x=new EmergencyContact{UserId=id,Name=r.Name.Trim(),Relationship=r.Relationship.Trim(),Phone=r.Phone.Trim(),Email=r.Email.Trim(),IsPrimary=r.IsPrimary};db.Add(x);await db.SaveChangesAsync();await audit.RecordAsync("EmergencyContactAdded","User",id.ToString(),actorUserId:HrId());return Ok(new{message="Emergency contact saved"});}
 [HttpGet("onboarding")]public async Task<IActionResult>Onboarding(string?search=null,string?status=null,string sort="joining",int page=1,int pageSize=10){var q=db.OnboardingRecords.Where(x=>x.AssignedHrId==HrId());if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.CandidateName.Contains(search)||x.OfficialEmail.Contains(search)||x.EmployeeCode.Contains(search));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);q=sort=="name"?q.OrderBy(x=>x.CandidateName):q.OrderBy(x=>x.JoiningDate);var total=await q.CountAsync();var items=await q.Skip((Math.Max(1,page)-1)*Math.Clamp(pageSize,5,100)).Take(Math.Clamp(pageSize,5,100)).ToListAsync();return Ok(Page(items,total,page,pageSize));}
 [HttpPatch("onboarding/{id:int}/stage")]public async Task<IActionResult>OnboardingStage(int id,OnboardingStageRequest r){var x=await db.OnboardingRecords.FirstOrDefaultAsync(x=>x.OnboardingId==id&&x.AssignedHrId==HrId());if(x==null)return NotFound();var stages=await Setting("OnboardingStages");var statuses=await Setting("OnboardingStageStatuses");if(!stages.Contains(r.Stage)||!statuses.Contains(r.Status))return BadRequest(new{message="Invalid onboarding stage or status"});switch(r.Stage){case"Documents":x.DocumentsStage=r.Status;break;case"Verification":x.VerificationStage=r.Status;break;case"Equipment":x.EquipmentStage=r.Status;break;case"Email":x.EmailStage=r.Status;break;case"Accounts":x.AccountsStage=r.Status;break;case"Training":x.TrainingStage=r.Status;break;case"Orientation":x.OrientationStage=r.Status;break;}var done=new[]{x.DocumentsStage,x.VerificationStage,x.EquipmentStage,x.EmailStage,x.AccountsStage,x.TrainingStage,x.OrientationStage}.Count(s=>s=="Completed");x.ProgressPercentage=(int)Math.Round(done*100d/7);x.Status=x.ProgressPercentage==100?"Ready to Complete":"In Progress";x.Remarks=r.Remarks?.Trim()??x.Remarks;await db.SaveChangesAsync();await audit.RecordAsync("OnboardingStageUpdated","OnboardingRecord",id.ToString(),actorUserId:HrId(),safeMetadata:new{r.Stage,r.Status,x.ProgressPercentage});return Ok(new{message="Onboarding stage updated",x.ProgressPercentage,x.Status});}
 [HttpGet("training")]public async Task<IActionResult>Training(string?search=null,string?status=null,int?departmentId=null,string sort="start",int page=1,int pageSize=10){var q=db.TrainingPrograms.Where(x=>x.AssignedHrId==HrId()).Include(x=>x.Assignments).ThenInclude(x=>x.User).AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Name.Contains(search)||x.Code.Contains(search)||x.Trainer.Contains(search));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);if(departmentId.HasValue)q=q.Where(x=>x.DepartmentId==departmentId);q=sort=="name"?q.OrderBy(x=>x.Name):q.OrderByDescending(x=>x.StartDate);var total=await q.CountAsync();var list=await q.Skip((Math.Max(1,page)-1)*Math.Clamp(pageSize,5,100)).Take(Math.Clamp(pageSize,5,100)).ToListAsync();var items=list.Select(x=>new{x.TrainingProgramId,x.Name,x.Code,x.Description,x.Trainer,x.DepartmentId,x.StartDate,x.EndDate,x.DeliveryMode,x.Location,x.Status,x.Remarks,enrollments=x.Assignments.Count,completed=x.Assignments.Count(a=>a.Status=="Completed"),averageScore=x.Assignments.Where(a=>a.Score.HasValue).Any()?Math.Round(x.Assignments.Where(a=>a.Score.HasValue).Average(a=>a.Score!.Value),2):0,assignments=x.Assignments.Select(a=>new{a.TrainingAssignmentId,a.UserId,employee=a.User!.FullName,a.Status,a.Score,a.CertificateUrl,a.AssignedAt,a.CompletedAt})}).ToList();return Ok(Page(items,total,page,pageSize));}
 [HttpPatch("training/assignments/{id:int}")]public async Task<IActionResult>TrainingResult(int id,TrainingResultRequest r){var x=await db.TrainingAssignments.Include(x=>x.TrainingProgram).FirstOrDefaultAsync(x=>x.TrainingAssignmentId==id&&x.TrainingProgram!.AssignedHrId==HrId());if(x==null)return NotFound();var statuses=await Setting("TrainingStatuses");if(!statuses.Contains(r.Status))return BadRequest(new{message="Invalid training status"});if(r.Score is <0 or >100)return BadRequest(new{message="Score must be between 0 and 100"});x.Status=r.Status;x.Score=r.Score;x.CertificateUrl=r.CertificateUrl?.Trim()??"";x.Remarks=r.Remarks?.Trim()??"";x.CompletedAt=r.Status=="Completed"?DateTime.UtcNow:null;await db.SaveChangesAsync();await audit.RecordAsync("TrainingResultUpdated","TrainingAssignment",id.ToString(),actorUserId:HrId(),safeMetadata:new{r.Status,r.Score});return Ok(new{message="Training result updated"});}
 [HttpGet("performance")]public async Task<IActionResult>Performance(int?year=null,string quarter="Q1",int?departmentId=null,string?classification=null,string sort="rating",int page=1,int pageSize=10){var y=year??DateTime.UtcNow.Year;IQueryable<User> people=People().Include(x=>x.Department);if(departmentId.HasValue)people=people.Where(x=>x.DepartmentId==departmentId);var total=await people.CountAsync();var users=await people.ToListAsync();var ids=users.Select(x=>x.UserId).ToList();var reviews=await db.PerformanceReviews.Where(x=>ids.Contains(x.EmployeeId)&&x.Year==y&&x.Quarter==quarter).ToListAsync();var rows=users.Select(u=>{var r=reviews.FirstOrDefault(x=>x.EmployeeId==u.UserId);return new{u.UserId,u.FullName,u.Role,department=u.Department?.Name,rating=r?.Rating,status=r==null?"Not Submitted":r.IsReleased?"Released":"Draft",r?.PromotionRecommendation,r?.Goals,r?.Kpis,r?.ManagerRemarks,classification=(r?.Rating??0)>=4?"Top Performer":r!=null&&r.Rating<2.5m?"Low Performer":"Core Performer"};});if(!string.IsNullOrWhiteSpace(classification))rows=rows.Where(x=>x.classification==classification);rows=sort=="name"?rows.OrderBy(x=>x.FullName):rows.OrderByDescending(x=>x.rating??0);var paged=rows.Skip((Math.Max(1,page)-1)*Math.Clamp(pageSize,5,100)).Take(Math.Clamp(pageSize,5,100)).ToList();var dept=rows.GroupBy(x=>x.department??"Unassigned").Select(g=>new{department=g.Key,people=g.Count(),averageRating=g.Where(x=>x.rating.HasValue).Any()?Math.Round(g.Where(x=>x.rating.HasValue).Average(x=>x.rating!.Value),2):0,topPerformers=g.Count(x=>x.classification=="Top Performer"),lowPerformers=g.Count(x=>x.classification=="Low Performer")});return Ok(new{items=paged,departmentKpis=dept,summary=new{reviewed=reviews.Count,topPerformers=rows.Count(x=>x.classification=="Top Performer"),lowPerformers=rows.Count(x=>x.classification=="Low Performer"),promotions=rows.Count(x=>x.PromotionRecommendation=="Recommended")},totalCount=rows.Count(),page=Math.Max(1,page),pageSize=Math.Clamp(pageSize,5,100),totalPages=(int)Math.Ceiling(rows.Count()/(double)Math.Clamp(pageSize,5,100))});}
 [HttpPost("promotions")]public async Task<IActionResult>Promotion(PromotionRequest r){var u=await People().FirstOrDefaultAsync(x=>x.UserId==r.UserId);if(u==null)return NotFound();if(string.IsNullOrWhiteSpace(r.ToDesignation)||r.EffectiveDate.Date<DateTime.UtcNow.Date)return BadRequest(new{message="Future effective date and designation are required"});var x=new PromotionHistory{UserId=u.UserId,FromDesignation=u.Designation??"",ToDesignation=r.ToDesignation.Trim(),EffectiveDate=r.EffectiveDate.Date,ApprovedById=HrId(),Remarks=r.Remarks?.Trim()??""};db.Add(x);db.Add(new Notification{UserId=u.UserId,Title="Promotion approved",Message=$"Promotion to {x.ToDesignation} effective {x.EffectiveDate:d}.",Type="Promotion",RelatedUrl="/employee/performance",DeduplicationKey=$"promotion:{u.UserId}:{x.EffectiveDate:yyyyMMdd}"});await db.SaveChangesAsync();await audit.RecordAsync("PromotionApproved","User",u.UserId.ToString(),actorUserId:HrId(),safeMetadata:new{x.FromDesignation,x.ToDesignation,x.EffectiveDate});return Ok(new{message="Promotion approved"});}
 [HttpGet("reports/dashboard")]public async Task<IActionResult>Reports(DateTime?from=null,DateTime?to=null,int?year=null){var start=(from??DateTime.UtcNow.Date.AddMonths(-11)).Date;var end=(to??DateTime.UtcNow.Date).Date.AddDays(1);var ids=await People().Select(x=>x.UserId).ToListAsync();var attendance=await db.Attendances.Where(x=>ids.Contains(x.UserId)&&x.AttendanceDate>=start&&x.AttendanceDate<end).ToListAsync();var leaves=await db.Leaves.Where(x=>ids.Contains(x.UserId)&&x.FromDate<end&&x.ToDate>=start).ToListAsync();var recruitment=await db.Applicants.Where(x=>x.AssignedHrId==HrId()&&x.AppliedAt>=start&&x.AppliedAt<end).ToListAsync();var training=await db.TrainingAssignments.Include(x=>x.TrainingProgram).Where(x=>ids.Contains(x.UserId)&&x.AssignedAt>=start&&x.AssignedAt<end).ToListAsync();var projects=await db.ProjectAssignments.Include(x=>x.Project).Where(x=>ids.Contains(x.UserId)).ToListAsync();var reviews=await db.PerformanceReviews.Where(x=>ids.Contains(x.EmployeeId)&&(year==null||x.Year==year)).ToListAsync();var trends=Enumerable.Range(0,12).Select(i=>start.AddMonths(i)).Where(m=>m<end).Select(m=>new{month=m.ToString("yyyy-MM"),attendance=attendance.Count(x=>x.AttendanceDate.Year==m.Year&&x.AttendanceDate.Month==m.Month),leave=leaves.Count(x=>x.FromDate.Year==m.Year&&x.FromDate.Month==m.Month),applicants=recruitment.Count(x=>x.AppliedAt.Year==m.Year&&x.AppliedAt.Month==m.Month),training=training.Count(x=>x.AssignedAt.Year==m.Year&&x.AssignedAt.Month==m.Month)});return Ok(new{counts=new{employees=ids.Count,attendance=attendance.Count,leave=leaves.Count,recruitment=recruitment.Count,performance=reviews.Count,training=training.Count,departments=await People().Where(x=>x.DepartmentId!=null).Select(x=>x.DepartmentId).Distinct().CountAsync(),projects=projects.Select(x=>x.ProjectId).Distinct().Count(),managers=await People().CountAsync(x=>x.Role=="Manager")},trends});}
 [HttpGet("reports/{type}/export")]public async Task<IActionResult>Export(string type,string format="csv",DateTime?from=null,DateTime?to=null){var rows=await Rows(type,from,to);if(rows.Count==0)rows.Add(new(){{"Message","No records match the selected filters"}});var safe=new string(type.Where(char.IsLetterOrDigit).ToArray()).ToLowerInvariant();var stamp=DateTime.UtcNow.ToString("yyyyMMdd");if(format.Equals("csv",StringComparison.OrdinalIgnoreCase))return File(Encoding.UTF8.GetBytes(Csv(rows)),"text/csv",$"hr-{safe}-{stamp}.csv");if(format.Equals("pdf",StringComparison.OrdinalIgnoreCase))return File(SimplePdf(rows),"application/pdf",$"hr-{safe}-{stamp}.pdf");using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("Report");var heads=rows.First().Keys.ToList();for(var i=0;i<heads.Count;i++)ws.Cell(1,i+1).Value=heads[i];for(var r=0;r<rows.Count;r++)for(var c=0;c<heads.Count;c++)ws.Cell(r+2,c+1).Value=Safe(rows[r].GetValueOrDefault(heads[c]));ws.Columns().AdjustToContents();using var ms=new MemoryStream();wb.SaveAs(ms);return File(ms.ToArray(),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",$"hr-{safe}-{stamp}.xlsx");}
 async Task<List<Dictionary<string,object?>>>Rows(string type,DateTime?from,DateTime?to){var ids=await People().Select(x=>x.UserId).ToListAsync();var start=from?.Date??DateTime.MinValue;var end=to?.Date.AddDays(1)??DateTime.MaxValue;switch(type.ToLowerInvariant()){case"attendance":return(await db.Attendances.Include(x=>x.User).Where(x=>ids.Contains(x.UserId)&&x.AttendanceDate>=start&&x.AttendanceDate<end).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Employee",x.User?.FullName},{"Date",x.AttendanceDate},{"Status",x.AttendanceStatus},{"Hours",x.EffectiveHours},{"Late",x.LateMinutes}}).ToList();case"leave":return(await db.Leaves.Include(x=>x.User).Where(x=>ids.Contains(x.UserId)&&x.FromDate<end&&x.ToDate>=start).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Employee",x.User?.FullName},{"Type",x.LeaveType},{"From",x.FromDate},{"To",x.ToDate},{"Status",x.Status}}).ToList();case"recruitment":return(await db.Applicants.Include(x=>x.Job).Where(x=>x.AssignedHrId==HrId()&&x.AppliedAt>=start&&x.AppliedAt<end).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Candidate",x.FullName},{"Job",x.Job?.Title},{"Applied",x.AppliedAt},{"Status",x.Status}}).ToList();case"training":return(await db.TrainingAssignments.Include(x=>x.User).Include(x=>x.TrainingProgram).Where(x=>ids.Contains(x.UserId)).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Employee",x.User?.FullName},{"Course",x.TrainingProgram?.Name},{"Status",x.Status},{"Score",x.Score}}).ToList();case"performance":return(await db.PerformanceReviews.Where(x=>ids.Contains(x.EmployeeId)).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"EmployeeId",x.EmployeeId},{"Year",x.Year},{"Quarter",x.Quarter},{"Rating",x.Rating},{"Promotion",x.PromotionRecommendation}}).ToList();case"department":return(await People().Include(x=>x.Department).ToListAsync()).GroupBy(x=>x.Department?.Name??"Unassigned").Select(g=>new Dictionary<string,object?>{{"Department",g.Key},{"People",g.Count()},{"Active",g.Count(x=>x.IsActive)},{"Managers",g.Count(x=>x.Role=="Manager")},{"Employees",g.Count(x=>x.Role=="Employee")}}).ToList();case"project":return(await db.ProjectAssignments.Include(x=>x.User).Include(x=>x.Project).Where(x=>ids.Contains(x.UserId)).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Employee",x.User?.FullName},{"Project",x.Project?.ProjectName},{"Status",x.Project?.Status},{"Progress",x.Project?.ProgressPercentage}}).ToList();case"manager":return(await People().Where(x=>x.Role=="Manager").ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Manager",x.FullName},{"Code",x.EmployeeCode},{"Reports",db.Users.Count(u=>u.ManagerId==x.UserId)},{"Status",x.IsActive?"Active":"Inactive"}}).ToList();default:return(await People().Include(x=>x.Department).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Employee",x.FullName},{"Code",x.EmployeeCode},{"Role",x.Role},{"Department",x.Department?.Name},{"Status",x.EmploymentStatus}}).ToList();}}
 async Task<string[]>Setting(string key)=>((await db.SystemSettings.Where(x=>x.SettingKey==key).Select(x=>x.SettingValue).FirstOrDefaultAsync())??"").Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries);static object Page<T>(List<T>items,int total,int page,int size)=>new{items,totalCount=total,page=Math.Max(1,page),pageSize=Math.Clamp(size,5,100),totalPages=(int)Math.Ceiling(total/(double)Math.Clamp(size,5,100))};static string Safe(object?v){var s=v?.ToString()??"";return s.Length>0&&"=+-@".Contains(s[0])?"'"+s:s;}static string Csv(List<Dictionary<string,object?>>r){var h=r.First().Keys.ToList();var b=new StringBuilder();b.AppendLine(string.Join(",",h.Select(x=>$"\"{x}\"")));foreach(var row in r)b.AppendLine(string.Join(",",h.Select(x=>$"\"{Safe(row.GetValueOrDefault(x)).Replace("\"","\"\"")}\"")));return b.ToString();}static byte[]SimplePdf(List<Dictionary<string,object?>>rows){var lines=new List<string>{"Employee Monitoring System Report",DateTime.UtcNow.ToString("u")};lines.AddRange(rows.Take(100).Select(x=>string.Join(" | ",x.Select(v=>$"{v.Key}: {Safe(v.Value)}"))));var text=string.Join("\\n",lines).Replace("(","[").Replace(")","]");var content=$"BT /F1 9 Tf 40 800 Td 0 -12 Td ({text.Replace("\\n",") Tj 0 -12 Td (")}) Tj ET";var objs=new[]{"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",$"<< /Length {Encoding.ASCII.GetByteCount(content)} >>\nstream\n{content}\nendstream","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"};var b=new StringBuilder("%PDF-1.4\n");var offsets=new List<int>{0};for(var i=0;i<objs.Length;i++){offsets.Add(Encoding.ASCII.GetByteCount(b.ToString()));b.Append($"{i+1} 0 obj\n{objs[i]}\nendobj\n");}var start=Encoding.ASCII.GetByteCount(b.ToString());b.Append($"xref\n0 {objs.Length+1}\n0000000000 65535 f \n");foreach(var o in offsets.Skip(1))b.Append($"{o:0000000000} 00000 n \n");b.Append($"trailer << /Size {objs.Length+1} /Root 1 0 R >>\nstartxref\n{start}\n%%EOF");return Encoding.ASCII.GetBytes(b.ToString());}
