public sealed class EmergencyContactRequest{public string Name{get;set;}="";public string Relationship{get;set;}="";public string Phone{get;set;}="";public string Email{get;set;}="";public bool IsPrimary{get;set;}}
public sealed class OnboardingStageRequest{public string Stage{get;set;}="";public string Status{get;set;}="";public string?Remarks{get;set;}}
public sealed class TrainingResultRequest{public string Status{get;set;}="";public decimal?Score{get;set;}public string?CertificateUrl{get;set;}public string?Remarks{get;set;}}
public sealed class PromotionRequest{public int UserId{get;set;}public string ToDesignation{get;set;}="";public DateTime EffectiveDate{get;set;}public string?Remarks{get;set;}}
